export function getGallery(slug: string) {
  return galleries.find(
    (gallery) => gallery.slug === slug,
  );
}

export function getPhoto(
  slug: string,
  photoId: string,
) {
  const gallery = getGallery(slug);

  if (!gallery) {
    return null;
  }

  const photoIndex =
    gallery.photos.findIndex(
      (photo) =>
        photo.id === photoId,
    );

  if (photoIndex === -1) {
    return null;
  }

  return {
    gallery,
    photo:
      gallery.photos[photoIndex],
    previousPhoto:
      photoIndex > 0
        ? gallery.photos[
            photoIndex - 1
          ]
        : null,
    nextPhoto:
      photoIndex <
      gallery.photos.length - 1
        ? gallery.photos[
            photoIndex + 1
          ]
        : null,
  };
}
